// Estimate the Lyapunov exponent of a 1D map f at x0.
// lambda = (1/N) sum_{k=0..N-1} log|f'(x_k)|.
// We differentiate numerically so any f works.
function f(x) {
  // try changing this:
  //   r * x * (1 - x)         // logistic with r below
  //   Math.cos(x)             // cosine map (mostly periodic)
  //   (x < 0.5 ? 2*x : 2 - 2*x) // tent map -> lambda = log 2
  const r = 4.0;
  return r * x * (1 - x);
}
function df(x) {
  const h = 1e-6;
  return (f(x + h) - f(x - h)) / (2 * h);
}
let x = 0.3;            // initial condition (avoid eventually-periodic seeds)
const burnin = 2000;
const N = 20000;
for (let k = 0; k < burnin; k++) x = f(x);
let sum = 0, valid = 0;
for (let k = 0; k < N; k++) {
  const d = Math.abs(df(x));
  if (d > 1e-12) { sum += Math.log(d); valid++; }
  x = f(x);
}
const lambda = sum / valid;
console.log('Lyapunov exponent estimate: ' + lambda.toFixed(4));
console.log('log(2) =                   ' + Math.log(2).toFixed(4));
console.log('positive => chaos; zero on the boundary; negative on periodic windows.');
